from django.conf import settings
from django.db import migrations, models

SECTIONS = ('About the app', 'Decisions', "How it's built", 'How the user likes to work')


def entries_to_documents(apps, schema_editor):
    """Each project's saved entries become lines of its memory document,
    under Decisions; a thread's pending ones wait on the thread as notes."""
    ProjectMemory = apps.get_model('Build', 'ProjectMemory')
    ProjectMemoryDocument = apps.get_model('Build', 'ProjectMemoryDocument')
    AgentConversation = apps.get_model('Build', 'AgentConversation')

    documents = {}
    for entry in ProjectMemory.objects.order_by('key', 'id'):
        line = ' '.join(f"{entry.key}: {entry.value}".split())[:400]
        if entry.status == 'proposed':
            if entry.source_id:
                thread = AgentConversation.objects.filter(id=entry.source_id).first()
                if thread is not None:
                    thread.memory_notes = list(thread.memory_notes or []) + [
                        {'section': 'Decisions', 'text': line}
                    ]
                    thread.save(update_fields=['memory_notes'])
            continue
        documents.setdefault((entry.user_id, entry.project_id), []).append(line)
    for (user_id, project_id), lines in documents.items():
        parts = []
        for section in SECTIONS:
            body = '\n'.join(f"- {line}" for line in lines) if section == 'Decisions' else ''
            parts.append(f"## {section}\n{body}" if body else f"## {section}")
        ProjectMemoryDocument.objects.update_or_create(
            user_id=user_id, project_id=project_id,
            defaults={'content': '\n\n'.join(parts) + '\n', 'version': 1},
        )


